using GraphApi.Models.SGR.Condominios;namespace GraphApi.Services.SGR.Condominios{    /// <summary>    /// Define las operaciones de negocio y persistencia para Condominios.    /// </summary>    public interface ICondominiosService    {        /// <summary>        /// Obtiene la lista de Condominios con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadCondominios>> GetCondominios(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Condominios con filtros opcionales.        /// </summary>        /// <param name="condominioID">Filtro opcional para CondominioID.</param>        /// <param name="nombreCondominio">Filtro opcional para NombreCondominio.</param>        /// <param name="direccionCondominio">Filtro opcional para DireccionCondominio.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetCondominiosDynamic(            int? condominioID,            string? nombreCondominio,            string? direccionCondominio,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Condominio.        /// </summary>        /// <param name="objInput">Datos para crear el Condominio.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCondominios> CreateCondominios(            clCreateCondominios objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Condominio.        /// </summary>        /// <param name="objInput">Datos para actualizar el Condominio, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCondominios?> UpdateCondominios(            clUpdateCondominios objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Condominio por su ID.        /// </summary>        /// <param name="nCondominiosID">ID del Condominio a eliminar.</param>        Task<bool> DeleteCondominios(int nCondominiosID);    }}